import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        int N = Integer.parseInt(line.trim());
        int[] dp = new int[7];
        for (int i = 1; i <= 6; i++) dp[i] = 0;

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int A = Integer.parseInt(st.nextToken());
            int B = Integer.parseInt(st.nextToken());
            int C = Integer.parseInt(st.nextToken());
            int D = Integer.parseInt(st.nextToken());
            int E = Integer.parseInt(st.nextToken());
            int F = Integer.parseInt(st.nextToken());

            int[] opp = new int[7];
            opp[A] = F; opp[F] = A;
            opp[B] = D; opp[D] = B;
            opp[C] = E; opp[E] = C;

            int[] faces = {A, B, C, D, E, F};
            int[] sideMax = new int[7];
            for (int b = 1; b <= 6; b++) {
                int top = opp[b];
                int max = 0;
                for (int f : faces) {
                    if (f != b && f != top) {
                        if (f > max) max = f;
                    }
                }
                sideMax[b] = max;
            }

            int[] new_dp = new int[7];
            Arrays.fill(new_dp, -1000000);
            for (int v = 1; v <= 6; v++) {
                if (dp[v] > -1000000) {
                    int top = opp[v];
                    int val = dp[v] + sideMax[v];
                    if (val > new_dp[top]) {
                        new_dp[top] = val;
                    }
                }
            }
            dp = new_dp;
        }

        int ans = 0;
        for (int v = 1; v <= 6; v++) {
            if (dp[v] > ans) ans = dp[v];
        }
        System.out.println(ans);
    }
}
